import { Easing, Interactive, Sequence, interpolate, useCurrentFrame, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface CenteredWordBuildProps {
  text: string;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  wordGap?: number;
  accel?: number;
  rise?: number;
  zoomStep?: number;
  settleFrames?: number;
  exitAt?: number;
  exitFrames?: number;
  speed?: number;
  className?: string;
}

function revealFrame(index: number, wordGap: number, accel: number): number {
  let frame = 0;

  for (let step = 1; step <= index; step++) {
    // Establish two even beats before tightening the cadence.
    frame += wordGap * accel ** Math.max(step - 2, 0);
  }

  return Math.round(frame);
}

function centeredWordBuildLength(
  text: string,
  wordGap = 11,
  accel = 0.75,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
): number {
  const words = text.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return 0;

  const lastReveal = revealFrame(words.length - 1, wordGap, accel);
  return Math.max(lastReveal + settleFrames, exitAt + exitFrames);
}

const settleEasing = Easing.bezier(0.16, 1, 0.3, 1);

function CenteredWordBuildBase({
  text,
  fontSize = 52,
  color = "#fff3df",
  fontWeight = 400,
  wordGap = 11,
  accel = 0.75,
  rise = 0.18,
  zoomStep = 0.035,
  settleFrames = 9,
  exitAt = 51,
  exitFrames = 12,
  speed = 1,
  className,
}: CenteredWordBuildProps) {
  const frame = useCurrentFrame() * speed;
  const words = text.trim().split(/\s+/).filter(Boolean);

  if (words.length === 0) return null;

  const visibleCount = words.filter(
    (_, index) => frame >= revealFrame(index, wordGap, accel),
  ).length;
  let cameraScale = 1;
  for (let index = 1; index < visibleCount; index++) {
    const revealAt = revealFrame(index, wordGap, accel);
    cameraScale +=
      zoomStep *
      interpolate(
        frame,
        [revealAt, revealAt + Math.max(settleFrames, 0.001)],
        [0, 1],
        {
          easing: settleEasing,
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        },
      );
  }
  const exitProgress = interpolate(
    frame,
    [exitAt, exitAt + Math.max(exitFrames, 0.001)],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    },
  );
  const fadeStart = -35 + exitProgress * 135;
  const fadeEnd = fadeStart + 35;
  const exitMask = `linear-gradient(90deg, transparent ${fadeStart}%, black ${fadeEnd}%)`;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          color,
          display: "inline-block",
          fontFamily:
            "var(--font-geist-sans, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif)",
          fontSize,
          fontWeight,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
          whiteSpace: "nowrap",
          scale: `${cameraScale}`,
          opacity: exitProgress >= 1 ? 0 : 1,
          maskImage: exitProgress > 0 ? exitMask : undefined,
          WebkitMaskImage: exitProgress > 0 ? exitMask : undefined,
          maskRepeat: "no-repeat",
          WebkitMaskRepeat: "no-repeat",
        }}
      >
        {words.slice(0, visibleCount).map((word, index) => {
          const revealAt = revealFrame(index, wordGap, accel);
          const y = interpolate(
            frame,
            [revealAt, revealAt + Math.max(settleFrames, 0.001)],
            [rise * fontSize, 0],
            {
              easing: settleEasing,
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            },
          );

          return (
            <span
              key={index}
              style={{
                display: "inline-block",
                marginLeft: index > 0 ? "0.25em" : undefined,
                translate: `0 ${y}px`,
              }}
            >
              {word}
            </span>
          );
        })}
      </span>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "everything we learn from",
    description: "Text",
  },
  fontSize: {
    type: "number",
    min: 24,
    max: 160,
    step: 1,
    default: 52,
    description: "Font size",
    hiddenFromList: false,
  },
  wordGap: {
    type: "number",
    min: 4,
    max: 24,
    step: 1,
    default: 11,
    description: "First word gaps",
    hiddenFromList: false,
  },
  accel: {
    type: "number",
    min: 0.4,
    max: 1,
    step: 0.05,
    default: 0.75,
    description: "Later gap multiplier",
    hiddenFromList: false,
  },
  rise: {
    type: "number",
    min: 0,
    max: 0.5,
    step: 0.01,
    default: 0.18,
    description: "Word rise (em)",
    hiddenFromList: false,
  },
  zoomStep: {
    type: "number",
    min: 0,
    max: 0.1,
    step: 0.005,
    default: 0.035,
    description: "Zoom / word",
    hiddenFromList: false,
  },
  settleFrames: {
    type: "number",
    min: 2,
    max: 20,
    step: 1,
    default: 9,
    description: "Rise and zoom frames",
    hiddenFromList: false,
  },
  exitAt: {
    type: "number",
    min: 20,
    max: 100,
    step: 1,
    default: 51,
    description: "Exit start frame",
    hiddenFromList: false,
  },
  exitFrames: {
    type: "number",
    min: 4,
    max: 30,
    step: 1,
    default: 12,
    description: "Exit duration",
    hiddenFromList: false,
  },
  color: {
    type: "color",
    default: "#fff3df",
    description: "Color",
  },
  fontWeight: {
    type: "enum",
    default: "400",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","fontSize","wordGap","accel","rise","zoomStep","settleFrames","exitAt","exitFrames","color","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "everything we learn from",
  fontSize: 52,
  wordGap: 11,
  accel: 0.75,
  rise: 0.18,
  zoomStep: 0.035,
  settleFrames: 9,
  exitAt: 51,
  exitFrames: 12,
  color: "#fff3df",
  fontWeight: "400",
  speed: 1,
};

type CenteredWordBuildElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CenteredWordBuildBase>;

const CenteredWordBuildInner = forwardRef<
  HTMLDivElement,
  CenteredWordBuildElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CenteredWordBuild>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CenteredWordBuildBase
          {...(componentProps as unknown as ComponentProps<typeof CenteredWordBuildBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CenteredWordBuild = Interactive.withSchema({
  Component: CenteredWordBuildInner,
  componentName: "<CenteredWordBuild>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
